"""Gateway verification code. Python 3. No network requests."""
import base64, hashlib, hmac, json
def decode(value):
    return base64.urlsafe_b64decode(value + '=' * (-len(value) % 4))
def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':')).encode()
def encode(value):
    return base64.urlsafe_b64encode(canonical(value)).rstrip(b'=').decode()
def verify(token, public_key):
    head, body, signature = token.strip().split('.')
    header, claims = json.loads(decode(head)), json.loads(decode(body))
    signed = (head + '.' + body).encode()
    raw_signature = decode(signature)
    if header['alg'] == 'RS256':
        from cryptography.hazmat.primitives import serialization, hashes
        from cryptography.hazmat.primitives.asymmetric import padding
        serialization.load_pem_public_key(public_key).verify(raw_signature, signed, padding.PKCS1v15(), hashes.SHA256())
    elif header['alg'] == 'HS256':
        assert hmac.compare_digest(raw_signature, hmac.new(public_key, signed, hashlib.sha256).digest()), 'signature rejected'
    else:
        raise ValueError('algorithm rejected')
    assert claims == {'aud': 'dda-vault', 'role': 'admin', 'sub': 'guest'}, 'admin access required'
    assert head == encode(header) and body == encode(claims), 'use canonical JSON'
    assert header == {'alg': header['alg'], 'typ': 'JWT'}, 'unexpected header fields'
    return raw_signature
def unwrap(token, public_key_pem, sealed_hex):
    signature = verify(token, public_key_pem.encode())
    blob = bytes.fromhex(sealed_hex)
    key = hashlib.sha256(signature).digest()
    mask = b''.join(hashlib.sha256(key + i.to_bytes(4, 'big')).digest() for i in range((len(blob)+31)//32))
    return bytes(a ^ b for a, b in zip(blob, mask)).decode()

