#include <stddef.h>
#include <stdint.h>

static const uint8_t expected[] = {
    0x12, 0xc2, 0x38, 0x37, 0x37, 0xfe, 0x2a, 0xb0,
    0x25, 0x05, 0x21, 0x74, 0xd3, 0x70, 0x02, 0x67,
    0x76, 0xd6, 0x6e, 0x1a, 0xc7, 0xfb, 0xdd, 0xb8,
    0xc2, 0x5d, 0x12, 0x20, 0xaa, 0x7c,
};

int check_flag(const uint8_t *input, size_t length) {
    if (length != sizeof(expected)) return 0;

    uint8_t state = 0x6d;
    unsigned difference = 0;
    for (size_t i = 0; i < length; i++) {
        unsigned shift = (i % 7) + 1;
        uint8_t x = input[i] ^ state;
        x = (uint8_t)((x << shift) | (x >> (8 - shift)));
        difference |= (uint8_t)(x + i * 17) ^ expected[i];
        state = (uint8_t)(state + input[i] + 0x37);
    }
    return difference == 0;
}

